import {describe, expect, it} from 'vitest';
import {codemodOutcome} from '../../../outcome.mjs';
import {
  dataTokenOwnershipOutcome,
  withDataTokenOwnershipOutcomes,
} from '../data-token-ownership-outcome.mjs';
import manifest from '../index.mjs';

const STALE =
  'This generated theme CSS still emits canonical data defaults at :root. Rebuild it with `astryx theme build`; defaults come from elsewhere.';
const DIRECT =
  'Direct var(--color-data-categorical-green) at line 4 needs manual migration: read it through dataVars.';
const RAW =
  'Raw var(--color-data-categorical-blue) without a fallback at line 2 needs an availability check: load the stylesheet.';

describe('validate-data-token-ownership outcomes', () => {
  it('types a stale generated theme as a regeneration with its command', () => {
    expect(codemodOutcome(dataTokenOwnershipOutcome(new Error(STALE)))).toEqual(
      {
        kind: 'regenerate',
        message: STALE,
        commands: ['astryx theme build'],
      },
    );
  });

  it('types raw-use reports as manual migrations, with the line when named', () => {
    expect(
      codemodOutcome(dataTokenOwnershipOutcome(new Error(DIRECT))),
    ).toEqual({
      kind: 'manual',
      message: DIRECT,
      line: 4,
    });
    expect(
      codemodOutcome(dataTokenOwnershipOutcome(new Error(RAW))),
    ).toMatchObject({
      kind: 'manual',
      line: 2,
    });
    const noLine =
      'Direct var(--color-data-categorical-green) needs manual migration: read it through dataVars.';
    expect(
      codemodOutcome(dataTokenOwnershipOutcome(new Error(noLine))),
    ).toEqual({
      kind: 'manual',
      message: noLine,
    });
  });

  it('fails closed: anything but an exact report prefix on a plain Error stays a failure', () => {
    for (const thrown of [
      // An Error subclass with report wording, such as a parse error.
      new SyntaxError(DIRECT),
      new TypeError(STALE),
      // The wording somewhere other than the start.
      new Error(`Unexpected token: ${DIRECT}`),
      new Error(`Failed: ${STALE}`),
      // Near misses.
      new Error('Direct var(--color-data-x) needs manual migration'),
      new Error(
        'Direct var(--color-brand) at line 1 needs manual migration: x',
      ),
      new Error('needs an availability check: something else'),
      new Error('This generated theme CSS still emits canonical data defaults'),
      'Direct var(--color-data-x) needs manual migration: not an Error',
    ]) {
      expect(dataTokenOwnershipOutcome(thrown)).toBe(thrown);
    }
  });

  it('wraps the manifest entry and passes results through', () => {
    const entry = manifest.find(
      t => t.name === 'validate-data-token-ownership',
    );
    const staleCss = `/* @generated by \`astryx theme build\` */\n:root { --color-data-categorical-green: #008000; }`;
    let thrown;
    try {
      entry.transform({source: staleCss, path: 'theme.css'}, {});
    } catch (err) {
      thrown = err;
    }
    expect(codemodOutcome(thrown)).toMatchObject({kind: 'regenerate'});
    expect(
      entry.transform({source: '.a { color: red; }', path: 'a.css'}, {}),
    ).toBeUndefined();
    expect(
      withDataTokenOwnershipOutcomes(() => 'x')({source: '', path: 'a'}, {}),
    ).toBe('x');
  });
});
